// @FIGURE_CODE_BEGIN
// ── element spec ─────────────────────────────────────────────────────────────
// axis shaft (solid)        → CylinderGeometry(0.02) MeshBasic black, depthTest false
// axis arrowhead            → ConeGeometry(0.095, 0.26) MeshBasic black
// hidden axis stub          → Line + LineDashedMaterial black (computeLineDistances)
// origin dot                → SphereGeometry(0.07) MeshBasic black
// panel a) teal bar         → PlaneGeometry(0.12, 0.70) teal, DoubleSide
// panel b) hyperplane line  → PlaneGeometry(len, 0.10) teal / terracotta quad
// panel c) hyperplane       → PlaneGeometry(4.5,4.5) transparent DoubleSide + EdgesGeometry outline
// half-space tint           → PlaneGeometry / BoxGeometry, clipped by shared THREE.Plane
// input point               → SphereGeometry(0.10) blue + dashed guide Lines + invisible pick sphere
// labels                    → addLabel (italic serif math)

const COL = { teal: 0x86cfc6, terra: 0xce6f4e, gray: 0xc7cac9,
              tealD: 0x4fa79b, terraD: 0x9d4a2c, grayD: 0x8f9392, pt: 0x1b3fbe };
const CSS = { teal: '#86CFC6', terra: '#CE6F4E', gray: '#A9ADAC' };
renderer.localClippingEnabled = true;

const V = (x, y, z) => new THREE.Vector3(x, y, z);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const MATH = s => `<span style="font-family:Georgia,'Times New Roman',serif;font-style:italic">${s}</span>`;

/* ── primitive builders ─────────────────────────────────────────────────── */
function inkMat() { const m = new THREE.MeshBasicMaterial({ color: 0x000000 }); m.depthTest = false; return m; }
function orientY(obj, dir) { obj.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize()); }

function shaftMesh(dir, len, r) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r || 0.02, r || 0.02, len, 10), inkMat());
  orientY(m, dir); m.position.copy(dir.clone().normalize().multiplyScalar(len / 2));
  m.renderOrder = 10; return m;
}
function headMesh(dir, at) {
  const hl = 0.26;
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.095, hl, 18), inkMat());
  orientY(m, dir); m.position.copy(dir.clone().normalize().multiplyScalar(at - hl / 2));
  m.renderOrder = 10; return m;
}
function dashedSeg(a, b, color, ds, gs) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const mat = new THREE.LineDashedMaterial({ color: color === undefined ? 0x000000 : color,
    dashSize: ds || 0.13, gapSize: gs || 0.09 });
  mat.depthTest = false;
  const l = new THREE.Line(g, mat); l.computeLineDistances(); l.renderOrder = 10; return l;
}
function axisRay(group, dir, len, dashed) {
  const dd = dir.clone().normalize();
  if (dashed) group.add(dashedSeg(dd.clone().multiplyScalar(0.06), dd.clone().multiplyScalar(len - 0.26)));
  else group.add(shaftMesh(dd, len - 0.26));
  group.add(headMesh(dd, len));
}
function originDot() {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.075, 20, 16), inkMat());
  m.renderOrder = 12; return m;
}
const clipPlane = new THREE.Plane(V(1, 0, 0), 0);
function tintMat(op) {
  return new THREE.MeshBasicMaterial({ color: COL.teal, transparent: true, opacity: op,
    side: THREE.DoubleSide, depthWrite: false, clippingPlanes: [clipPlane] });
}

/* ── panel a) : 1D ──────────────────────────────────────────────────────── */
const gA = new THREE.Group();
axisRay(gA, V(1, 0, 0), 3.0, false);
axisRay(gA, V(-1, 0, 0), 3.0, false);
const barA = new THREE.Mesh(new THREE.PlaneGeometry(0.12, 0.70),
  new THREE.MeshBasicMaterial({ color: COL.teal, side: THREE.DoubleSide }));
barA.position.z = -0.002; gA.add(barA);
const tintA = new THREE.Mesh(new THREE.PlaneGeometry(6.4, 0.70), tintMat(0.20));
tintA.position.z = -0.01; tintA.renderOrder = 0; gA.add(tintA);
gA.add(originDot());

/* ── panel b) : 2D ──────────────────────────────────────────────────────── */
const gB = new THREE.Group();
axisRay(gB, V(1, 0, 0), 3.0, false);
axisRay(gB, V(-1, 0, 0), 3.0, false);
axisRay(gB, V(0, 1, 0), 3.0, false);
axisRay(gB, V(0, -1, 0), 3.0, false);
function lineQuad(len, color) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(len, 0.10),
    new THREE.MeshBasicMaterial({ color: color, side: THREE.DoubleSide }));
  return m;
}
const lineTeal = lineQuad(5.2, COL.teal); lineTeal.position.z = -0.003; gB.add(lineTeal);
const lineTerra = lineQuad(4.8, COL.terra); lineTerra.position.z = -0.004; gB.add(lineTerra);
const tintB = new THREE.Mesh(new THREE.PlaneGeometry(6.4, 6.4), tintMat(0.18));
tintB.position.z = -0.02; tintB.renderOrder = 0; gB.add(tintB);
gB.add(originDot());

/* ── panel c) : 3D ──────────────────────────────────────────────────────── */
const gC = new THREE.Group();
function makePlane(size, color, dark, order) {
  const geo = new THREE.PlaneGeometry(size, size);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: color, transparent: true,
    opacity: 0.78, side: THREE.DoubleSide, depthWrite: false }));
  mesh.renderOrder = order;
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: dark, transparent: true, opacity: 0.45 }));
  edges.renderOrder = order; mesh.add(edges);
  mesh.userData.edges = edges;
  return mesh;
}
const planeGray = makePlane(4.6, COL.gray, COL.grayD, 1);   // x3 = 0  (spans x1,x2)
const planeTerra = makePlane(4.5, COL.terra, COL.terraD, 2); // x2 = 0  (spans x1,x3)
const planeTeal = makePlane(4.5, COL.teal, COL.tealD, 3);   // x1 = 0  (spans x2,x3)
gC.add(planeGray, planeTerra, planeTeal);
axisRay(gC, V(1, 0, 0), 2.85, false);   // +x1 right
axisRay(gC, V(-1, 0, 0), 2.85, true);   // -x1 (behind gray plane) dashed
axisRay(gC, V(0, 1, 0), 2.85, false);   // +x2 up
axisRay(gC, V(0, -1, 0), 2.85, true);   // -x2 dashed
axisRay(gC, V(0, 0, 1), 2.25, false);   // +x3 toward lower-left front
axisRay(gC, V(0, 0, -1), 1.95, true);   // -x3 dashed toward upper-right rear
const tintC = new THREE.Mesh(new THREE.BoxGeometry(4.5, 4.5, 4.5), tintMat(0.13));
tintC.renderOrder = 0; gC.add(tintC);
gC.add(originDot());

/* ── input point (always in scene) ──────────────────────────────────────── */
const pt = V(1.35, 0, 0);
const gPoint = new THREE.Group();
const ptMat = new THREE.MeshBasicMaterial({ color: COL.pt }); ptMat.depthTest = false;
const ptMesh = new THREE.Mesh(new THREE.SphereGeometry(0.105, 20, 16), ptMat);
ptMesh.renderOrder = 14; gPoint.add(ptMesh);
const ptPick = new THREE.Mesh(new THREE.SphereGeometry(0.30, 12, 10),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
gPoint.add(ptPick);
let guideLine = null;
scene.add(gPoint);

/* ── neurons ────────────────────────────────────────────────────────────── */
const neurons = {
  teal:  { key: 'teal',  color: COL.teal,  css: CSS.teal,  name: 'teal neuron',
           base: V(1, 0, 0), axis2: V(0, 0, 1), axis3: V(0, 1, 0), eq: 'x\u2081 = 0' },
  terra: { key: 'terra', color: COL.terra, css: CSS.terra, name: 'orange neuron',
           base: V(0, 1, 0), axis2: V(0, 0, 1), axis3: V(0, 0, 1), eq: 'x\u2082 = 0' },
  gray:  { key: 'gray',  color: COL.gray,  css: CSS.gray,  name: 'gray neuron',
           base: V(0, 0, 1), axis2: V(0, 1, 0), axis3: V(0, 1, 0), eq: 'x\u2083 = 0' }
};
let dim = 1, selected = 'teal', tilt = 1, showTint = true;
const activeKeys = () => (dim === 1 ? ['teal'] : dim === 2 ? ['teal', 'terra'] : ['teal', 'terra', 'gray']);

function normalOf(key) {
  const n = neurons[key], sel = (key === selected), s = sel ? tilt : 1;
  if (dim === 1) return V(s >= 0 ? 1 : -1, 0, 0);
  const th = sel ? (s - 1) * THREE.MathUtils.degToRad(25) : 0;
  return n.base.clone().applyAxisAngle(dim === 2 ? n.axis2 : n.axis3, th).normalize();
}
function weightVec(key) {
  const sel = (key === selected), s = sel ? tilt : 1;
  if (dim === 1) return V(s, 0, 0);
  const mag = sel ? Math.max(Math.abs(s), 0.05) : 1;
  return normalOf(key).multiplyScalar(mag);
}
function preAct(key) {
  const w = weightVec(key);
  return w.x * pt.x + w.y * pt.y + w.z * pt.z;
}

/* ── labels ─────────────────────────────────────────────────────────────── */
const labA = [], labB = [], labC = [];
const F = { fontSize: '17px' }, P = { fontSize: '20px' };
labA.push(addLabel('a)', V(-3.35, 0.95, 0), P));
labA.push(addLabel(MATH('x') + '<sub>1</sub>', V(3.05, -0.33, 0), F));
labB.push(addLabel('b)', V(-3.35, 3.05, 0), P));
labB.push(addLabel(MATH('x') + '<sub>1</sub>', V(3.05, -0.35, 0), F));
labB.push(addLabel(MATH('x') + '<sub>2</sub>', V(0.55, 3.15, 0), F));
labC.push(addLabel('c)', V(-3.5, 3.05, 0), P));
labC.push(addLabel(MATH('x') + '<sub>1</sub>', V(3.05, -0.30, 0), F));
labC.push(addLabel(MATH('x') + '<sub>2</sub>', V(0.42, 3.05, 0), F));
labC.push(addLabel(MATH('x') + '<sub>3</sub>', V(0, -0.18, 2.55), { fontSize: '17px', offset: [-26, 12] }));
const ptLabel = addLabel(MATH('x'), V(0, 0, 0), { fontSize: '15px', color: '#1b3fbe', bold: true, offset: [14, -12] });

/* ── selectable boundaries ──────────────────────────────────────────────── */
const selectables = [
  { mesh: barA, key: 'teal', dim: 1 },
  { mesh: lineTeal, key: 'teal', dim: 2 },
  { mesh: lineTerra, key: 'terra', dim: 2 },
  { mesh: planeTeal, key: 'teal', dim: 3 },
  { mesh: planeTerra, key: 'terra', dim: 3 },
  { mesh: planeGray, key: 'gray', dim: 3 }
];
const activeSelectables = () => selectables.filter(s => s.dim === dim).map(s => s.mesh);
function keyOfMesh(m) { const e = selectables.find(s => s.mesh === m); return e ? e.key : null; }

/* ── geometry refresh ───────────────────────────────────────────────────── */
function refresh() {
  const nSel = normalOf(selected);
  clipPlane.set(nSel.clone(), 0);

  if (dim === 1) {
    tintA.material.color.setHex(neurons[selected].color);
    tintA.visible = showTint;
  } else if (dim === 2) {
    const nT = normalOf('teal'), nO = normalOf('terra');
    lineTeal.rotation.z = Math.atan2(nT.x, -nT.y);
    lineTerra.rotation.z = Math.atan2(nO.x, -nO.y);
    tintB.material.color.setHex(neurons[selected].color);
    tintB.visible = showTint;
  } else {
    planeTeal.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('teal'));
    planeTerra.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('terra'));
    planeGray.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('gray'));
    tintC.material.color.setHex(neurons[selected].color);
    tintC.visible = showTint;
  }
  // selection emphasis
  selectables.forEach(s => {
    const on = (s.key === selected);
    if (s.mesh.material.opacity !== undefined && s.dim === 3) {
      s.mesh.material.opacity = on ? 0.88 : 0.68;
      s.mesh.userData.edges.material.opacity = on ? 0.95 : 0.35;
    }
  });
  // input point
  gPoint.position.set(pt.x, pt.y, pt.z);
  ptLabel.pos.set(pt.x, pt.y, pt.z);
  if (guideLine) { gC.remove(guideLine); scene.remove(guideLine); guideLine.geometry.dispose(); guideLine = null; }
  if (dim >= 2) {
    const pts = [V(0, 0, 0), V(pt.x, 0, pt.z), V(pt.x, pt.y, pt.z)];
    guideLine = dashedSeg(pts[0], pts[1], 0x1b3fbe, 0.10, 0.08);
    guideLine.geometry.dispose();
    guideLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
    guideLine.computeLineDistances();
    guideLine.material.opacity = 0.7; guideLine.material.transparent = true;
    scene.add(guideLine);
  }
  updateUI();
}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const dimBtns = { 1: document.getElementById('dim1'), 2: document.getElementById('dim2'), 3: document.getElementById('dim3') };
const selBtns = { teal: document.getElementById('selTeal'), terra: document.getElementById('selTerra'), gray: document.getElementById('selGray') };
const slider = document.getElementById('tiltWeight');
const tiltVal = document.getElementById('tiltVal');
const chkTint = document.getElementById('chkTint');
const ptRead = document.getElementById('ptRead');
const signRead = document.getElementById('signRead');
const regionRead = document.getElementById('regionRead');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function fmtW(w) {
  if (dim === 1) return '(' + w.x.toFixed(2) + ')';
  if (dim === 2) return '(' + w.x.toFixed(2) + ', ' + w.y.toFixed(2) + ')';
  return '(' + w.x.toFixed(2) + ', ' + w.y.toFixed(2) + ', ' + w.z.toFixed(2) + ')';
}
function updateUI() {
  for (const k in dimBtns) dimBtns[k].classList.toggle('active', +k === dim);
  const keys = activeKeys();
  for (const k in selBtns) {
    selBtns[k].disabled = keys.indexOf(k) < 0;
    selBtns[k].style.opacity = selBtns[k].disabled ? 0.4 : 1;
    selBtns[k].classList.toggle('active', k === selected);
  }
  tiltVal.textContent = (+tilt).toFixed(2);
  let coords = 'x\u2081 = ' + pt.x.toFixed(2);
  if (dim >= 2) coords += ',  x\u2082 = ' + pt.y.toFixed(2);
  if (dim >= 3) coords += ',  x\u2083 = ' + pt.z.toFixed(2);
  ptRead.textContent = coords;
  let html = '', signs = [];
  keys.forEach(k => {
    const z = preAct(k), s = z >= 0 ? '+' : '\u2212';
    signs.push(s);
    html += '<div><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:' +
      neurons[k].css + ';margin-right:5px"></span>' +
      (k === selected ? '<b>' : '') + 'w = ' + fmtW(weightVec(k)) +
      ' &rarr; z = ' + z.toFixed(2) + ' <b style="color:' + (z >= 0 ? '#1a7f37' : '#b02a2a') + '">' + s + '</b>' +
      (k === selected ? '</b>' : '') + '</div>';
  });
  signRead.innerHTML = html;
  regionRead.innerHTML = 'sign pattern <b>(' + signs.join(', ') + ')</b> &rarr; region ' +
    (1 + signs.reduce((a, s, i) => a + (s === '+' ? (1 << i) : 0), 0)) + ' of ' + Math.pow(2, keys.length);
}

function setDim(n) {
  dim = n;
  scene.remove(gA); scene.remove(gB); scene.remove(gC);
  scene.add(n === 1 ? gA : n === 2 ? gB : gC);
  [labA, labB, labC].forEach((arr, i) => arr.forEach(e => { e.div.style.visibility = (i === n - 1) ? 'visible' : 'hidden'; }));
  ptLabel.div.style.visibility = 'visible';
  if (activeKeys().indexOf(selected) < 0) selected = 'teal';
  if (n < 3) pt.z = 0;
  if (n < 2) pt.y = 0;
  const L = n === 3 ? 2.1 : 2.6;
  pt.set(clamp(pt.x, -L, L), clamp(pt.y, -L, L), clamp(pt.z, -L, L));
  controls.enableRotate = (n === 3);
  refresh();
  if (n === 3) setCameraView({ projection: 'perspective', azimuthDeg: 30, elevationDeg: 18, rollDeg: 0, heightFraction: 0.6 });
  else setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 0, rollDeg: 0, heightFraction: n === 1 ? 0.85 : 0.82 });
}

for (const k in dimBtns) (function (kk) { dimBtns[kk].addEventListener('click', () => setDim(+kk)); })(k);
for (const k in selBtns) (function (kk) { selBtns[kk].addEventListener('click', () => { selected = kk; refresh(); }); })(k);
slider.addEventListener('input', () => { tilt = parseFloat(slider.value); refresh(); });
chkTint.addEventListener('change', () => { showTint = chkTint.checked; refresh(); });

/* ── picking: hover + click-to-select + drag the input point ────────────── */
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const dragPlane = new THREE.Plane();
let dragging = false, downX = 0, downY = 0, moved = 0;

function setNDC(e) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', e => {
  downX = e.clientX; downY = e.clientY; moved = 0;
  setNDC(e); ray.setFromCamera(ndc, camera);
  if (ray.intersectObject(ptPick, false).length) {
    dragging = true; controls.enabled = false;
    if (dim === 3) {
      const nrm = camera.getWorldDirection(V(0, 0, 0)).negate();
      dragPlane.setFromNormalAndCoplanarPoint(nrm, pt.clone());
    } else dragPlane.set(V(0, 0, 1), 0);
    try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
  }
});
canvas.addEventListener('pointermove', e => {
  moved += Math.abs(e.clientX - downX) + Math.abs(e.clientY - downY);
  if (dragging) {
    setNDC(e); ray.setFromCamera(ndc, camera);
    const hit = V(0, 0, 0);
    if (ray.ray.intersectPlane(dragPlane, hit)) {
      const L = dim === 3 ? 2.1 : 2.6;
      pt.x = clamp(hit.x, -L, L);
      pt.y = dim >= 2 ? clamp(hit.y, -L, L) : 0;
      pt.z = dim >= 3 ? clamp(hit.z, -L, L) : 0;
      refresh();
    }
    return;
  }
  setNDC(e); ray.setFromCamera(ndc, camera);
  if (ray.intersectObject(ptPick, false).length) {
    canvas.style.cursor = 'move';
    showTooltip('Drag the input point x', e);
    return;
  }
  const hits = ray.intersectObjects(activeSelectables(), false);
  if (hits.length) {
    const k = keyOfMesh(hits[0].object);
    canvas.style.cursor = 'pointer';
    showTooltip(neurons[k].name + ' — boundary ' + neurons[k].eq + ' (click to select)', e);
  } else {
    canvas.style.cursor = dim === 3 ? 'grab' : 'default';
    hideTooltip();
  }
});
window.addEventListener('pointerup', e => {
  if (dragging) { dragging = false; controls.enabled = true; return; }
  if (moved > 6) return;
  setNDC(e); ray.setFromCamera(ndc, camera);
  const hits = ray.intersectObjects(activeSelectables(), false);
  if (!hits.length) return;
  const k = keyOfMesh(hits[0].object);
  if (!k) return;
  selected = k; refresh();
  const obj = dim === 1 ? 'point' : dim === 2 ? 'line' : 'plane';
  showPopup(neurons[k].name,
    'This ' + obj + ' is the set of inputs where this neuron\'s pre-activation z = w\u00B7x + b equals zero ' +
    '(by default ' + neurons[k].eq + '). Inputs on the tinted side give z > 0; on the untinted side z < 0. ' +
    'Move the weight slider to rotate it.');
});
canvas.addEventListener('pointerleave', () => { hideTooltip(); });

/* ── guided demo ────────────────────────────────────────────────────────── */
