<div id="stepText" style="color:#444;line-height:1.35"></div>

<div style="margin-top:7px;color:#666;line-height:1.35">In panel c) the axes are drawn <b>dashed exactly where a plane hides them</b> &mdash; orbit the view and watch the dashing follow the real occlusion.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── element spec ─────────────────────────────────────────────────────────────
// axis shaft (visible run)  → CylinderGeometry(r=0.022) MeshBasic black, depthTest:false
// axis arrowhead            → ConeGeometry(0.10, 0.28) MeshBasic black
// axis run hidden by plane  → Line + LineDashedMaterial black (rebuilt per camera move)
// origin dot                → SphereGeometry(0.085) MeshBasic black
// a) teal bar               → PlaneGeometry(0.135, 0.80) teal, DoubleSide
// b) teal / terracotta bars → PlaneGeometry(len, 0.115) rotated quads
// c) gray / terra / teal    → PlaneGeometry + EdgesGeometry outline, transparent
// half-space tint           → Plane / Box + shared THREE.Plane clipping (default OFF)
// input point               → SphereGeometry(0.07) blue + dashed guide + invisible pick sphere
// labels                    → addLabel, italic serif math, 22px next to arrow tips

const COL = { teal: 0x8FD2C9, terra: 0xCE6F4E, gray: 0xC3C7C6,
              tealD: 0x4fa79b, terraD: 0x9d4a2c, grayD: 0x8f9392, pt: 0x1b3fbe };
const CSS = { teal: '#8FD2C9', terra: '#CE6F4E', gray: '#A9ADAC' };
renderer.localClippingEnabled = true;

const V = (x, y, z) => new THREE.Vector3(x, y, z);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const MATH = s => `<span style="font-family:Georgia,'Times New Roman',serif;font-style:italic">${s}</span>`;

/* ── primitive builders ─────────────────────────────────────────────────── */
function inkMat() { const m = new THREE.MeshBasicMaterial({ color: 0x000000 }); m.depthTest = false; return m; }
function orientY(obj, dir) { obj.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize()); }
function tube(a, b, r) {
  const dir = b.clone().sub(a), len = dir.length();
  if (len < 1e-4) return null;
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), inkMat());
  orientY(m, dir); m.position.copy(a).addScaledVector(dir, 0.5); m.renderOrder = 10; return m;
}
function headMesh(dir, at) {
  const hl = 0.28;
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.10, hl, 18), inkMat());
  orientY(m, dir); m.position.copy(dir.clone().normalize().multiplyScalar(at - hl / 2));
  m.renderOrder = 11; return m;
}
function dashedSeg(a, b, color, ds, gs) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const mat = new THREE.LineDashedMaterial({ color: color === undefined ? 0x000000 : color,
    dashSize: ds || 0.12, gapSize: gs || 0.09 });
  mat.depthTest = false;
  const l = new THREE.Line(g, mat); l.computeLineDistances(); l.renderOrder = 10; return l;
}
function axisSolid(group, dir, len) {
  const dd = dir.clone().normalize();
  const t = tube(V(0, 0, 0), dd.clone().multiplyScalar(len - 0.28), 0.022);
  if (t) group.add(t);
  group.add(headMesh(dd, len));
}
function originDot() {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.085, 20, 16), inkMat());
  m.renderOrder = 12; return m;
}
const clipPlane = new THREE.Plane(V(1, 0, 0), 0);
function tintMat(op) {
  return new THREE.MeshBasicMaterial({ color: COL.teal, transparent: true, opacity: op,
    side: THREE.DoubleSide, depthWrite: false, clippingPlanes: [clipPlane] });
}

/* ── panel groups ───────────────────────────────────────────────────────── */
const gA = new THREE.Group(), gB = new THREE.Group(), gC = new THREE.Group();
const panels = { a: gA, b: gB, c: gC };

/* ── panel a) : 1D ──────────────────────────────────────────────────────── */
axisSolid(gA, V(1, 0, 0), 3.0);
axisSolid(gA, V(-1, 0, 0), 3.0);
const barA = new THREE.Mesh(new THREE.PlaneGeometry(0.135, 0.80),
  new THREE.MeshBasicMaterial({ color: COL.teal, side: THREE.DoubleSide }));
barA.position.z = 0.002; barA.renderOrder = 2; gA.add(barA);
const tintA = new THREE.Mesh(new THREE.PlaneGeometry(5.9, 0.80), tintMat(0.17));
tintA.position.z = -0.01; tintA.renderOrder = 0; gA.add(tintA);
gA.add(originDot());

/* ── panel b) : 2D ──────────────────────────────────────────────────────── */
axisSolid(gB, V(1, 0, 0), 3.0); axisSolid(gB, V(-1, 0, 0), 3.0);
axisSolid(gB, V(0, 1, 0), 3.0); axisSolid(gB, V(0, -1, 0), 3.0);
function lineQuad(len, color) {
  return new THREE.Mesh(new THREE.PlaneGeometry(len, 0.115),
    new THREE.MeshBasicMaterial({ color: color, side: THREE.DoubleSide }));
}
const lineTeal = lineQuad(5.0, COL.teal); lineTeal.position.z = 0.002; lineTeal.renderOrder = 2; gB.add(lineTeal);
const lineTerra = lineQuad(5.0, COL.terra); lineTerra.position.z = 0.004; lineTerra.renderOrder = 3; gB.add(lineTerra);
const tintB = new THREE.Mesh(new THREE.PlaneGeometry(5.6, 5.6), tintMat(0.15));
tintB.position.z = -0.02; tintB.renderOrder = 0; gB.add(tintB);
gB.add(originDot());

/* ── panel c) : 3D ──────────────────────────────────────────────────────── */
function makePlane(w, h, color, dark, order) {
  const geo = new THREE.PlaneGeometry(w, h);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: color, transparent: true,
    opacity: 0.85, side: THREE.DoubleSide, depthWrite: false }));
  mesh.renderOrder = order;
  mesh.userData.hw = w / 2; mesh.userData.hh = h / 2;
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: dark, transparent: true, opacity: 0.35 }));
  edges.renderOrder = order; mesh.add(edges); mesh.userData.edges = edges;
  return mesh;
}
const planeGray  = makePlane(4.8, 4.2, COL.gray,  COL.grayD,  1);  // x3 = 0 (spans x1,x2)
const planeTeal  = makePlane(3.4, 4.8, COL.teal,  COL.tealD,  2);  // x1 = 0 (spans x3,x2)
const planeTerra = makePlane(5.0, 3.4, COL.terra, COL.terraD, 3);  // x2 = 0 (spans x1,x3)
gC.add(planeGray, planeTeal, planeTerra);
const planesC = [planeGray, planeTeal, planeTerra];
const axesC = new THREE.Group(); gC.add(axesC);
const tintC = new THREE.Mesh(new THREE.BoxGeometry(4.4, 4.4, 3.2), tintMat(0.12));
tintC.renderOrder = 0; gC.add(tintC);
gC.add(originDot());

const AXC = [
  { dir: V(1, 0, 0),  len: 2.90 },
  { dir: V(-1, 0, 0), len: 2.90 },
  { dir: V(0, 1, 0),  len: 2.80 },
  { dir: V(0, -1, 0), len: 2.80 },
  { dir: V(0, 0, 1),  len: 2.35 },
  { dir: V(0, 0, -1), len: 2.10 }
];
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const o = g.children[i]; g.remove(o);
    o.geometry && o.geometry.dispose && o.geometry.dispose();
    o.material && o.material.dispose && o.material.dispose();
  }
}
// Dash an axis run only where a plane really occludes it (recomputed on orbit).
function buildAxesC() {
  clearGroup(axesC);
  gC.updateMatrixWorld(true);
  const invW = new THREE.Matrix4().copy(gC.matrixWorld).invert();
  const camDirLocal = camera.getWorldDirection(V(0, 0, 0)).negate().transformDirection(invW).normalize();
  const camPosLocal = camera.position.clone().applyMatrix4(invW);
  const info = planesC.map(pm => {
