/* ── primitive builders ─────────────────────────────────────────────────── */
function inkMat() { const m = new THREE.MeshBasicMaterial({ color: 0x000000 }); m.depthTest = false; return m; }
function orientY(obj, dir) { obj.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize()); }
function tube(a, b, r) {
  const dir = b.clone().sub(a), len = dir.length();
  if (len < 1e-4) return null;
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), inkMat());
  orientY(m, dir); m.position.copy(a).addScaledVector(dir, 0.5); m.renderOrder = 10; return m;
}
function headMesh(dir, at) {
  const hl = 0.28;
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.10, hl, 18), inkMat());
  orientY(m, dir); m.position.copy(dir.clone().normalize().multiplyScalar(at - hl / 2));
  m.renderOrder = 11; return m;
}
function dashedSeg(a, b, color, ds, gs) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const mat = new THREE.LineDashedMaterial({ color: color === undefined ? 0x000000 : color,
    dashSize: ds || 0.12, gapSize: gs || 0.09 });
  mat.depthTest = false;
  const l = new THREE.Line(g, mat); l.computeLineDistances(); l.renderOrder = 10; return l;
}
function axisSolid(group, dir, len) {
  const dd = dir.clone().normalize();
  const t = tube(V(0, 0, 0), dd.clone().multiplyScalar(len - 0.28), 0.022);
  if (t) group.add(t);
  group.add(headMesh(dd, len));
}
function originDot() {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.085, 20, 16), inkMat());
  m.renderOrder = 12; return m;
}
const clipPlane = new THREE.Plane(V(1, 0, 0), 0);
function tintMat(op) {
  return new THREE.MeshBasicMaterial({ color: COL.teal, transparent: true, opacity: op,
    side: THREE.DoubleSide, depthWrite: false, clippingPlanes: [clipPlane] });
}

