const neurons = {
  teal:  { key: 'teal',  color: COL.teal,  css: CSS.teal,  name: 'teal neuron',
           base: V(1, 0, 0), axis3: V(0, 1, 0), eq: 'x\u2081 = 0' },
  terra: { key: 'terra', color: COL.terra, css: CSS.terra, name: 'orange neuron',
           base: V(0, 1, 0), axis3: V(0, 0, 1), eq: 'x\u2082 = 0' },
  gray:  { key: 'gray',  color: COL.gray,  css: CSS.gray,  name: 'gray neuron',
           base: V(0, 0, 1), axis3: V(0, 1, 0), eq: 'x\u2083 = 0' }
};
let panelMode = 1, dim = 1, selected = 'teal', tilt = 1, showTint = false, showPt = false;
const activeKeys = () => (dim === 1 ? ['teal'] : dim === 2 ? ['teal', 'terra'] : ['teal', 'terra', 'gray']);

function normalOf(key, d) {
  const n = neurons[key], sel = (key === selected), s = sel ? tilt : 1;
  if (d === 1) return V(s >= 0 ? 1 : -1, 0, 0);
  const th = sel ? (s - 1) * THREE.MathUtils.degToRad(22) : 0;
  const axis = d === 2 ? V(0, 0, 1) : n.axis3;
  return n.base.clone().applyAxisAngle(axis, th).normalize();
}
function weightVec(key) {
  const sel = (key === selected), s = sel ? tilt : 1;
  if (dim === 1) return V(s, 0, 0);
  const mag = sel ? Math.max(Math.abs(s), 0.05) : 1;
  return normalOf(key, dim).multiplyScalar(mag);
}
function preAct(key) { const w = weightVec(key); return w.x * pt.x + w.y * pt.y + w.z * pt.z; }

