/* ── baked rotation so panel c keeps its 3D look in the side-by-side view ─ */
const VIEW3 = { az: 70, el: 13 };
const dir3 = V(Math.cos(THREE.MathUtils.degToRad(VIEW3.az)) * Math.cos(THREE.MathUtils.degToRad(VIEW3.el)),
               Math.sin(THREE.MathUtils.degToRad(VIEW3.el)),
               Math.sin(THREE.MathUtils.degToRad(VIEW3.az)) * Math.cos(THREE.MathUtils.degToRad(VIEW3.el)));
const bakeQ = new THREE.Quaternion().setFromRotationMatrix(
  new THREE.Matrix4().lookAt(dir3.clone().multiplyScalar(10), V(0, 0, 0), V(0, 1, 0))).invert();

/* ── label layout ───────────────────────────────────────────────────────── */
function layoutLabels() {
  scene.updateMatrixWorld(true);
  const small = (panelMode === 'all');
  LBL.forEach(l => {
    const g = panels[l.panel];
    const vis = (panelMode === 'all') ? true
      : (l.panel === 'a' && panelMode === 1) || (l.panel === 'b' && panelMode === 2) || (l.panel === 'c' && panelMode === 3);
    l.e.div.style.visibility = vis ? 'visible' : 'hidden';
    l.e.div.style.fontSize = small ? (l.big ? '13px' : '12px') : (l.big ? '22px' : '20px');
    if (vis && g.parent) l.e.pos.copy(g.localToWorld(l.base.clone()));
  });
  const act = panelMode === 'all' ? null : (panelMode === 1 ? gA : panelMode === 2 ? gB : gC);
  ptLabel.div.style.visibility = (showPt && act) ? 'visible' : 'hidden';
  if (act && act.parent) ptLabel.pos.copy(act.localToWorld(pt.clone()));
}

/* ── geometry refresh ───────────────────────────────────────────────────── */
function refresh() {
  const nA = normalOf('teal', 1);
  const nBt = normalOf('teal', 2), nBo = normalOf('terra', 2);
  lineTeal.rotation.z = Math.atan2(nBt.x, -nBt.y);
  lineTerra.rotation.z = Math.atan2(nBo.x, -nBo.y);
  planeTeal.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('teal', 3));
  planeTerra.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('terra', 3));
  planeGray.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('gray', 3));

  const nSel = (dim === 1) ? nA : normalOf(selected, dim);
  clipPlane.set(nSel.clone(), 0);
  const tintOn = showTint && panelMode !== 'all';
  tintA.visible = tintOn && panelMode === 1;
  tintB.visible = tintOn && panelMode === 2;
  tintC.visible = tintOn && panelMode === 3;
  [tintA, tintB, tintC].forEach(t => t.material.color.setHex(neurons[selected].color));

  selectables.forEach(s => {
    const on = (s.key === selected);
    if (s.dim === 3) {
      s.mesh.material.opacity = on ? 0.92 : 0.74;
      s.mesh.userData.edges.material.opacity = on ? 0.9 : 0.3;
    } else {
      s.mesh.scale.y = on ? 1.25 : 1.0;
    }
  });

  const act = panelMode === 'all' ? null : (panelMode === 1 ? gA : panelMode === 2 ? gB : gC);
  if (guideLine) { if (guideLine.parent) guideLine.parent.remove(guideLine); guideLine.geometry.dispose(); guideLine = null; }
  if (gPoint.parent) gPoint.parent.remove(gPoint);
  if (act && showPt) {
    act.add(gPoint);
    gPoint.position.copy(pt);
    if (dim >= 2) {
      const pts = [V(0, 0, 0), V(pt.x, 0, pt.z), V(pt.x, pt.y, pt.z)];
      guideLine = dashedSeg(pts[0], pts[1], COL.pt, 0.10, 0.08);
      guideLine.geometry.dispose();
      guideLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
      guideLine.computeLineDistances();
      guideLine.material.transparent = true; guideLine.material.opacity = 0.75;
      act.add(guideLine);
    }
  }
  if (gC.parent) buildAxesC();
  layoutLabels();
  updateUI();
}

