function fmtW(w) {
  if (dim === 1) return '(' + w.x.toFixed(2) + ')';
  if (dim === 2) return '(' + w.x.toFixed(2) + ', ' + w.y.toFixed(2) + ')';
  return '(' + w.x.toFixed(2) + ', ' + w.y.toFixed(2) + ', ' + w.z.toFixed(2) + ')';
}
function updateUI() {
  for (const k in dimBtns) dimBtns[k].classList.toggle('active', String(panelMode) === k);
  const keys = activeKeys();
  for (const k in selBtns) {
    selBtns[k].disabled = keys.indexOf(k) < 0;
    selBtns[k].style.opacity = selBtns[k].disabled ? 0.4 : 1;
    selBtns[k].classList.toggle('active', k === selected);
  }
  tiltVal.textContent = (+tilt).toFixed(2);
  chkTint.checked = showTint; chkPoint.checked = showPt;
  const on = showPt && panelMode !== 'all';
  ptBlock.style.display = on ? '' : 'none';
  if (!on) return;
  let coords = 'x\u2081 = ' + pt.x.toFixed(2);
  if (dim >= 2) coords += ',  x\u2082 = ' + pt.y.toFixed(2);
  if (dim >= 3) coords += ',  x\u2083 = ' + pt.z.toFixed(2);
  ptRead.textContent = coords;
  let html = '', signs = [];
  keys.forEach(k => {
    const z = preAct(k), s = z >= 0 ? '+' : '\u2212';
    signs.push(s);
    html += '<div><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:' +
      neurons[k].css + ';margin-right:5px"></span>' +
      (k === selected ? '<b>' : '') + 'w = ' + fmtW(weightVec(k)) +
      ' &rarr; z = ' + z.toFixed(2) + ' <b style="color:' + (z >= 0 ? '#1a7f37' : '#b02a2a') + '">' + s + '</b>' +
      (k === selected ? '</b>' : '') + '</div>';
  });
  signRead.innerHTML = html;
  regionRead.innerHTML = 'sign pattern <b>(' + signs.join(', ') + ')</b> &rarr; region ' +
    (1 + signs.reduce((a, s, i) => a + (s === '+' ? (1 << i) : 0), 0)) + ' of ' + Math.pow(2, keys.length);
}

/* ── mode switching (1D / 2D / 3D / all panels side-by-side) ────────────── */
function setMode(m) {
  panelMode = m;
  dim = (m === 'all') ? 3 : m;
  [gA, gB, gC].forEach(p => { if (p.parent) p.parent.remove(p); });
  if (m === 'all') {
    gA.position.set(-4.5, 0, 0); gA.scale.setScalar(0.50); gA.quaternion.identity();
    gB.position.set(0.1, 0, 0);  gB.scale.setScalar(0.50); gB.quaternion.identity();
    gC.position.set(4.7, 0, 0);  gC.scale.setScalar(0.50); gC.quaternion.copy(bakeQ);
    scene.add(gA); scene.add(gB); scene.add(gC);
  } else {
    const p = m === 1 ? gA : m === 2 ? gB : gC;
    p.position.set(0, 0, 0); p.scale.setScalar(1); p.quaternion.identity();
    scene.add(p);
  }
  if (activeKeys().indexOf(selected) < 0) selected = 'teal';
  if (dim < 3) pt.z = 0;
  if (dim < 2) pt.y = 0;
  const Lm = dim === 3 ? 2.0 : 2.5;
  pt.set(clamp(pt.x, -Lm, Lm), clamp(pt.y, -Lm, Lm), clamp(pt.z, -Lm, Lm));
  controls.enableRotate = (m === 3);
  refresh();
  if (m === 3) setCameraView({ projection: 'orthographic', azimuthDeg: VIEW3.az, elevationDeg: VIEW3.el, heightFraction: 0.72 });
  else if (m === 'all') setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.82 });
  else setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: m === 1 ? 0.70 : 0.76 });
  layoutLabels();
}

for (const k in dimBtns) (function (kk) {
  dimBtns[kk].addEventListener('click', () => setMode(kk === 'all' ? 'all' : +kk));
})(k);
for (const k in selBtns) (function (kk) {
  selBtns[kk].addEventListener('click', () => { selected = kk; refresh(); });
})(k);
slider.addEventListener('input', () => { tilt = parseFloat(slider.value); refresh(); });
chkTint.addEventListener('change', () => { showTint = chkTint.checked; refresh(); });
chkPoint.addEventListener('change', () => { showPt = chkPoint.checked; refresh(); });

/* ── rebuild the occlusion dashing whenever the camera moves ────────────── */
let lastCamKey = '';
(function watchCam() {
  requestAnimationFrame(watchCam);
  if (!gC.parent) return;
  const k = camera.position.toArray().map(v => v.toFixed(2)).join(',') + '|' + camera.zoom.toFixed(3);
  if (k !== lastCamKey) { lastCamKey = k; buildAxesC(); }
})();

/* ── picking: hover + click-to-select + drag the input point ────────────── */
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const dragPlane = new THREE.Plane();
let dragging = false, downX = 0, downY = 0, moved = 0;

function setNDC(e) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', e => {
  downX = e.clientX; downY = e.clientY; moved = 0;
  setNDC(e); ray.setFromCamera(ndc, camera);
  if (showPt && gPoint.parent && ray.intersectObject(ptPick, false).length) {
    dragging = true; controls.enabled = false;
    if (panelMode === 3) {
      const nrm = camera.getWorldDirection(V(0, 0, 0)).negate();
      dragPlane.setFromNormalAndCoplanarPoint(nrm, pt.clone());
    } else dragPlane.set(V(0, 0, 1), 0);
    try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
  }
});
canvas.addEventListener('pointermove', e => {
  moved += Math.abs(e.clientX - downX) + Math.abs(e.clientY - downY);
  if (dragging) {
    setNDC(e); ray.setFromCamera(ndc, camera);
    const hit = V(0, 0, 0);
    if (ray.ray.intersectPlane(dragPlane, hit)) {
      const Lm = dim === 3 ? 2.0 : 2.5;
      pt.x = clamp(hit.x, -Lm, Lm);
      pt.y = dim >= 2 ? clamp(hit.y, -Lm, Lm) : 0;
      pt.z = dim >= 3 ? clamp(hit.z, -Lm, Lm) : 0;
      refresh();
    }
    return;
  }
  setNDC(e); ray.setFromCamera(ndc, camera);
  if (showPt && gPoint.parent && ray.intersectObject(ptPick, false).length) {
    canvas.style.cursor = 'move';
    showTooltip('Drag the input point x', e);
    return;
  }
  const hits = ray.intersectObjects(activeSelectables(), false);
  if (hits.length) {
    const k = keyOfMesh(hits[0].object);
    canvas.style.cursor = 'pointer';
    showTooltip(neurons[k].name + ' \u2014 boundary ' + neurons[k].eq + ' (click to select)', e);
  } else {
    canvas.style.cursor = panelMode === 3 ? 'grab' : 'default';
    hideTooltip();
  }
});
window.addEventListener('pointerup', e => {
  if (dragging) { dragging = false; controls.enabled = true; return; }
  if (moved > 6) return;
  setNDC(e); ray.setFromCamera(ndc, camera);
  const hits = ray.intersectObjects(activeSelectables(), false);
  if (!hits.length) return;
  const k = keyOfMesh(hits[0].object);
  if (!k) return;
  selected = k; refresh();
  const obj = dim === 1 ? 'point' : dim === 2 ? 'line' : 'plane';
  showPopup(neurons[k].name,
    'This ' + obj + ' is the set of inputs where this neuron\u2019s pre-activation z = w\u00B7x + b equals zero ' +
    '(by default ' + neurons[k].eq + '). Inputs on one side give z > 0, on the other z < 0 \u2014 tick ' +
    '\u201CTint positive half-space\u201D to shade them. Move the weight slider to rotate this boundary.');
});
canvas.addEventListener('pointerleave', () => { hideTooltip(); });

/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { title: '1D: the hyperplane is a point', mode: 1, w: 1, pt: false, tint: false,
    text: 'On a single input axis x\u2081 the pre-activation w\u00B7x\u2081 + b changes sign at exactly one location. That point (teal) is the hyperplane.' },
  { title: 'Which side is positive?', mode: 1, w: -1, pt: true, tint: true,
    text: 'The tint marks where z > 0. Flipping the weight to w = \u22121 swaps the positive side; the boundary itself does not move.' },
  { title: '2D: two neurons, two lines', mode: 2, w: 1, pt: true, tint: false,
    text: 'With inputs (x\u2081, x\u2082) each neuron\u2019s boundary is a line through the origin \u2014 teal for one neuron, orange for another. Together they cut the plane into four sign regions.' },
  { title: 'Tilt one line', mode: 2, w: 2.2, pt: true, tint: true,
    text: 'Changing the selected neuron\u2019s weight rotates only its line, re-shaping the half-spaces and possibly moving the dragged input point into a different region.' },
  { title: '3D: hyperplanes become planes', mode: 3, w: 1, pt: false, tint: false,
    text: 'In three dimensions each boundary is a flat plane. The axes are dashed exactly where a plane hides them \u2014 orbit the view and the dashing updates with the true occlusion.' },
  { title: 'All three side by side', mode: 'all', w: 1, pt: false, tint: false,
    text: 'The same construction in 1D, 2D and 3D: a hyperplane always has one dimension less than the input space \u2014 point, line, plane. The weight slider tilts the teal boundary in all three panels at once.' }
];
let stepIdx = 0, tweenRaf = null, playTimer = null;
function tweenTilt(target) {
  const start = tilt, t0 = performance.now(), dur = 520;
  if (tweenRaf) cancelAnimationFrame(tweenRaf);
  const stepFn = () => {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    tilt = start + (target - start) * e;
    slider.value = tilt; refresh();
    if (k < 1) tweenRaf = requestAnimationFrame(stepFn);
    else { tilt = target; slider.value = tilt; refresh(); }
  };
  stepFn();
}
function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const st = steps[stepIdx];
  showPt = st.pt; showTint = st.tint;
  selected = 'teal';
  if (st.mode !== panelMode) setMode(st.mode); else refresh();
  tweenTilt(st.w);
  stepTitle.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + st.title;
  stepText.textContent = st.text;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPlay').addEventListener('click', function () {
  if (playTimer) { clearInterval(playTimer); playTimer = null; this.textContent = 'Play'; return; }
  this.textContent = 'Stop';
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 5200);
});

/* ── start: clean 1D panel, exactly the source composition ──────────────── */
setMode(1);
stepIdx = 0;
stepTitle.textContent = '1/' + steps.length + '  ' + steps[0].title;
stepText.textContent = steps[0].text;
// @FIGURE_CODE_END

