// @FIGURE_CODE_BEGIN
/* ── element spec ─────────────────────────────────────────────────────────
 // axis shaft (visible run)  → CylinderGeometry(r=0.02) MeshBasic black
 // axis run hidden by plane  → Line + LineDashedMaterial black (rebuilt on camera move)
 // axis arrowhead            → ConeGeometry(0.095,0.30) MeshBasic black
 // origin dot                → SphereGeometry(0.075) MeshBasic black, on top
 // a) teal point-hyperplane  → PlaneGeometry(0.15,0.85) teal, DoubleSide
 // b) teal line / orange line→ PlaneGeometry(0.15,4.0)/(3.75,0.17) rotated quads
 // c) gray  plane  x3=0      → PlaneGeometry(4.5,4.9)  gray
 // c) teal  plane  x1=0      → PlaneGeometry(6.0,4.4)  teal   (width along x3)
 // c) orange plane x2=0      → PlaneGeometry(4.3,6.0)  terracotta
 // half-space tint (opt-in)  → Plane/Box slab offset to the +normal side
 // input point (opt-in)      → SphereGeometry(0.07) blue + dashed drop guide
 // labels                    → addLabel: a) b) c), x1, x2, x3 (italic serif)
*/

const HP = { teal: 0x8FD2C9, terra: 0xCE6F4E, gray: 0xC3C7C6,
             tealD: 0x2f7d72, terraD: 0x9d4a2c, grayD: 0x76807e, pt: 0x1b3fbe };
const CSSC = { teal: '#7cc6bb', terra: '#CE6F4E', gray: '#9ea2a1' };
const V = (x, y, z) => new THREE.Vector3(x, y, z);
const cl = (v, a, b) => Math.max(a, Math.min(b, v));
const MTH = s => '<span style="font-family:Georgia,\'Times New Roman\',serif;font-style:italic">' + s + '</span>';
const XL = n => MTH('x') + '<sub>' + n + '</sub>';
const cv = renderer.domElement;

const INK = new THREE.MeshBasicMaterial({ color: 0x000000 });
const INK_TOP = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 1 });
INK_TOP.depthTest = false;
const DASH = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.13, gapSize: 0.10,
  transparent: true, opacity: 1 });
DASH.depthTest = false;

/* ── primitive builders ────────────────────────────────────────────────── */
function tube(a, b, r, mat, order) {
  const dir = b.clone().sub(a), len = dir.length();
  if (len < 1e-4) return null;
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), mat);
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize());
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.renderOrder = order; return m;
}
function head(dir, at, mat, order) {
  const hl = 0.30;
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.095, hl, 16), mat);
  const dd = dir.clone().normalize();
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dd);
  m.position.copy(dd).multiplyScalar(at - hl / 2);
  m.renderOrder = order; return m;
}
function axisArrow(g, dir, len, mat, order) {
  const dd = dir.clone().normalize();
  const t = tube(V(0, 0, 0), dd.clone().multiplyScalar(len - 0.28), 0.02, mat, order);
  if (t) g.add(t);
  g.add(head(dd, len, mat, order));
}
function originDot() {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.075, 18, 14), INK_TOP);
  m.renderOrder = 12; return m;
}
function barQuad(w, h, color) {
  const mat = new THREE.MeshBasicMaterial({ color: color, side: THREE.DoubleSide,
    transparent: true, opacity: 1 });
  mat.depthTest = false;
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  return m;
}
function slab(kind) {
  let geo;
  if (kind === 1) geo = new THREE.PlaneGeometry(5.2, 0.9);
  else if (kind === 2) geo = new THREE.PlaneGeometry(5.2, 5.2);
  else geo = new THREE.BoxGeometry(5.2, 5.2, 5.2);
  geo.translate(2.6, 0, 0);
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: HP.teal, transparent: true,
    opacity: kind === 3 ? 0.13 : 0.18, side: THREE.DoubleSide, depthWrite: false }));
  m.renderOrder = 0; return m;
}

/* ── panel a) 1D ───────────────────────────────────────────────────────── */
const gA = new THREE.Group();
axisArrow(gA, V(1, 0, 0), 2.55, INK, 0);
axisArrow(gA, V(-1, 0, 0), 2.55, INK, 0);
const barA = barQuad(0.15, 0.85, HP.teal); barA.renderOrder = 5; gA.add(barA);
gA.add(originDot());
const tintA = slab(1);

/* ── panel b) 2D ───────────────────────────────────────────────────────── */
const gB = new THREE.Group();
axisArrow(gB, V(1, 0, 0), 2.5, INK, 0);
axisArrow(gB, V(-1, 0, 0), 2.5, INK, 0);
axisArrow(gB, V(0, 1, 0), 2.6, INK, 0);
axisArrow(gB, V(0, -1, 0), 2.6, INK, 0);
const lineTeal = barQuad(4.0, 0.15, HP.teal);  lineTeal.renderOrder = 5;  gB.add(lineTeal);
const lineTerra = barQuad(3.75, 0.17, HP.terra); lineTerra.renderOrder = 6; gB.add(lineTerra);
gB.add(originDot());
const tintB = slab(2);

/* ── panel c) 3D ───────────────────────────────────────────────────────── */
function planeMesh(w, h, color, dark, order) {
  const geo = new THREE.PlaneGeometry(w, h);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: color, transparent: true,
    opacity: 0.94, side: THREE.DoubleSide, depthWrite: false }));
  mesh.renderOrder = order;
  mesh.userData.hw = w / 2; mesh.userData.hh = h / 2;
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: dark, transparent: true, opacity: 0.95 }));
  e.visible = false; e.renderOrder = order; mesh.add(e); mesh.userData.edges = e;
  return mesh;
}
const gC = new THREE.Group();
const planeGray  = planeMesh(4.5, 4.9, HP.gray,  HP.grayD,  1);   // x3 = 0
const planeTeal  = planeMesh(6.0, 4.4, HP.teal,  HP.tealD,  2);   // x1 = 0
const planeTerra = planeMesh(4.3, 6.0, HP.terra, HP.terraD, 3);   // x2 = 0
gC.add(planeGray, planeTeal, planeTerra);
const planesC = [planeGray, planeTeal, planeTerra];
const axesC = new THREE.Group(); gC.add(axesC);
gC.add(originDot());
const tintC = slab(3);
const panels = { a: gA, b: gB, c: gC };

const AXC = [
  { d: V(1, 0, 0), L: 2.55 }, { d: V(-1, 0, 0), L: 2.90 },
  { d: V(0, 1, 0), L: 2.85 }, { d: V(0, -1, 0), L: 2.75 },
  { d: V(0, 0, 1), L: 3.00 }, { d: V(0, 0, -1), L: 3.00 }
];

function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const o = g.children[i]; g.remove(o);
    if (o.geometry && o.geometry.dispose) o.geometry.dispose();
  }
}
// Direction from the scene toward the viewer, valid under the oblique shear too
// (unproject uses the live projectionMatrixInverse).
function viewerDir() {
  const a = V(0, 0, -1).unproject(camera), b = V(0, 0, 1).unproject(camera);
  return a.sub(b).normalize();
}
// Dash an axis run ONLY where a plane really occludes it.
function buildAxesC() {
  clearGroup(axesC);
  const vd = viewerDir();
  const info = planesC.map(pm => {
    pm.updateMatrix();
    return { inv: new THREE.Matrix4().copy(pm.matrix).invert(), hw: pm.userData.hw, hh: pm.userData.hh };
  });
  const far = 40;
  const hidden = (p) => {
    const q = p.clone().addScaledVector(vd, far);
    for (const pi of info) {
      const a = p.clone().applyMatrix4(pi.inv), b = q.clone().applyMatrix4(pi.inv);
      if ((a.z <= 0 && b.z <= 0) || (a.z >= 0 && b.z >= 0)) continue;
      const t = a.z / (a.z - b.z);
      if (t < 0.002 || t > 1) continue;
      const ix = a.x + (b.x - a.x) * t, iy = a.y + (b.y - a.y) * t;
      if (Math.abs(ix) <= pi.hw && Math.abs(iy) <= pi.hh) return true;
    }
    return false;
  };
  AXC.forEach(ax => {
    const dd = ax.d.clone().normalize(), L = ax.L - 0.28, N = 40;
    const runs = []; let cur = null;
    for (let i = 0; i < N; i++) {
      const t0 = L * i / N, t1 = L * (i + 1) / N;
      const h = (t1 < 0.06) ? false : hidden(dd.clone().multiplyScalar((t0 + t1) / 2));
      if (!cur || cur.h !== h) { cur = { h: h, a: t0, b: t1 }; runs.push(cur); } else cur.b = t1;
    }
    runs.forEach(r => {
      const p0 = dd.clone().multiplyScalar(r.a), p1 = dd.clone().multiplyScalar(r.b);
      if (r.h) {
        const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([p0, p1]), DASH);
        l.computeLineDistances(); l.renderOrder = 11; axesC.add(l);
      } else {
        const t = tube(p0, p1, 0.02, INK_TOP, 10); if (t) axesC.add(t);
      }
    });
    axesC.add(head(dd, ax.L, INK_TOP, 10));
  });
}

/* ── input point ───────────────────────────────────────────────────────── */
const ptPos = V(1.40, 0, 0);
const gPoint = new THREE.Group();
const ptMat = new THREE.MeshBasicMaterial({ color: HP.pt, transparent: true, opacity: 1 });
ptMat.depthTest = false;
const ptMesh = new THREE.Mesh(new THREE.SphereGeometry(0.07, 18, 14), ptMat);
ptMesh.renderOrder = 14; gPoint.add(ptMesh);
const ptPick = new THREE.Mesh(new THREE.SphereGeometry(0.26, 12, 10),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
gPoint.add(ptPick);
let guideLine = null;

/* ── neurons ───────────────────────────────────────────────────────────── */
const neurons = {
  teal:  { color: HP.teal,  css: CSSC.teal,  name: 'teal neuron',   base: V(1, 0, 0), ax3: V(0, 1, 0), eq: 'x\u2081 = 0' },
  terra: { color: HP.terra, css: CSSC.terra, name: 'orange neuron', base: V(0, 1, 0), ax3: V(0, 0, 1), eq: 'x\u2082 = 0' },
  gray:  { color: HP.gray,  css: CSSC.gray,  name: 'gray neuron',   base: V(0, 0, 1), ax3: V(0, 1, 0), eq: 'x\u2083 = 0' }
};
let panelMode = 'all', dim = 3, selected = 'teal', tilt = 1, showTint = false, showPt = false, engaged = false;
const activeKeys = () => (dim === 1 ? ['teal'] : dim === 2 ? ['teal', 'terra'] : ['teal', 'terra', 'gray']);

function normalOf(key, k) {
  const n = neurons[key], sel = (key === selected), s = sel ? tilt : 1;
  if (k === 1) return V(s >= 0 ? 1 : -1, 0, 0);
  const th = sel ? (s - 1) * THREE.MathUtils.degToRad(20) : 0;
  const axis = (k === 2) ? V(0, 0, 1) : n.ax3;
  return n.base.clone().applyAxisAngle(axis, th).normalize();
}
function weightVec(key) {
  const sel = (key === selected), s = sel ? tilt : 1;
  if (dim === 1) return V(s, 0, 0);
  const mag = sel ? Math.max(Math.abs(s), 0.05) * (s < 0 ? -1 : 1) : 1;
  return normalOf(key, dim).multiplyScalar(Math.abs(mag)).multiplyScalar(sel && s < 0 ? -1 : 1);
}
function preAct(key) { const w = weightVec(key); return w.dot(ptPos); }

/* ── labels ────────────────────────────────────────────────────────────── */
const LBL = [];
function L(panel, html, base, big) {
  const e = addLabel(html, V(0, 0, 0), { fontSize: '14px' });
  LBL.push({ e: e, panel: panel, base: base, big: !!big });
  return e;
}
L('a', 'a)', V(-3.50, 2.85, 0), false);
L('a', XL(1), V(3.05, -0.32, 0), true);
L('b', 'b)', V(-3.30, 2.85, 0), false);
L('b', XL(1), V(3.02, -0.34, 0), true);
L('b', XL(2), V(0.52, 2.62, 0), true);
L('c', 'c)', V(-3.95, 2.90, 0), false);
L('c', XL(1), V(3.10, -0.32, 0), true);
L('c', XL(2), V(-0.58, 2.92, 0), true);
const lblX3 = L('c', XL(3), V(0, -0.10, 3.10), true);
lblX3.offset = [-14, 16];
const ptLabel = addLabel(MTH('x'), V(0, 0, 0), { fontSize: '15px', color: '#1b3fbe', bold: true, offset: [14, -12] });

function layoutLabels() {
  const small = (panelMode === 'all');
  LBL.forEach(l => {
    const g = panels[l.panel];
    const vis = (panelMode === 'all') ? true
      : (l.panel === 'a' && panelMode === 1) || (l.panel === 'b' && panelMode === 2) || (l.panel === 'c' && panelMode === 3);
    l.e.div.style.visibility = vis ? 'visible' : 'hidden';
    l.e.div.style.fontSize = small ? '14px' : (l.big ? '21px' : '19px');
    if (vis) l.e.pos.copy(l.base).add(g.position);
  });
  const act = actGroup();
