}

/* ── selectable boundaries + scaffold hover/click explainers ───────────── */
const selectables = [
  { mesh: barA,       key: 'teal',  k: 1, what: 'point' },
  { mesh: lineTeal,   key: 'teal',  k: 2, what: 'line' },
  { mesh: lineTerra,  key: 'terra', k: 2, what: 'line' },
  { mesh: planeTeal,  key: 'teal',  k: 3, what: 'plane' },
  { mesh: planeTerra, key: 'terra', k: 3, what: 'plane' },
  { mesh: planeGray,  key: 'gray',  k: 3, what: 'plane' }
];
function refreshInteractive() {
  _interactiveObjects.length = 0;
  const list = (panelMode === 'all') ? selectables : selectables.filter(s => s.k === panelMode);
  list.forEach(s => {
    const n = neurons[s.key];
    registerInteractive(s.mesh, {
      title: n.name + ' \u2014 hyperplane (' + s.what + ')',
      tooltip: n.name + ': boundary ' + n.eq + ' \u2014 click to select',
      body: 'This ' + s.what + ' is the set of inputs where this neuron\u2019s pre-activation ' +
            'z = w\u00B7x + b is exactly zero (here ' + n.eq + '). On one side z > 0, on the other z < 0. ' +
            'In a ' + s.k + 'D input space a hyperplane always has ' + (s.k - 1) + ' dimension' +
            (s.k - 1 === 1 ? '' : 's') + '. Use the weight slider to rotate it, or tick ' +
