/* ── geometry refresh ──────────────────────────────────────────────────── */
function refresh() {
  const nBt = normalOf('teal', 2), nBo = normalOf('terra', 2);
  lineTeal.rotation.z = Math.atan2(nBt.x, -nBt.y);
  lineTerra.rotation.z = Math.atan2(nBo.x, -nBo.y);
  planeTeal.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('teal', 3));
  planeTerra.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('terra', 3));
  planeGray.quaternion.setFromUnitVectors(V(0, 0, 1), normalOf('gray', 3));
  barA.scale.x = (dim === 1 && tilt < 0) ? 1 : 1;

  // emphasis only once the student has started interacting (default = printed look)
  selectables.forEach(s => {
    const on = engaged && s.key === selected;
    if (s.k === 3) { s.mesh.userData.edges.visible = on; s.mesh.material.opacity = on ? 1 : 0.94; }
    else s.mesh.scale.y = on ? 1.35 : 1;
  });

  // half-space tint
  [tintA, tintB, tintC].forEach(t => { if (t.parent) t.parent.remove(t); });
  const act = actGroup();
  if (showTint && act) {
    const t = panelMode === 1 ? tintA : panelMode === 2 ? tintB : tintC;
    const n = normalOf(selected, dim);
    t.quaternion.setFromUnitVectors(V(1, 0, 0), n);
    t.material.color.setHex(neurons[selected].color);
    act.add(t);
  }

  // input point + drop guide
  if (guideLine) { if (guideLine.parent) guideLine.parent.remove(guideLine); guideLine.geometry.dispose(); guideLine = null; }
  if (gPoint.parent) gPoint.parent.remove(gPoint);
  if (act && showPt) {
    act.add(gPoint); gPoint.position.copy(ptPos);
    if (dim >= 2) {
      const pts = [V(0, 0, 0), V(ptPos.x, 0, ptPos.z), V(ptPos.x, ptPos.y, ptPos.z)];
      const mat = new THREE.LineDashedMaterial({ color: HP.pt, dashSize: 0.11, gapSize: 0.09,
        transparent: true, opacity: 0.8 });
      mat.depthTest = false;
      guideLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
      guideLine.computeLineDistances(); guideLine.renderOrder = 13;
      act.add(guideLine);
    }
  }
  if (gC.parent) buildAxesC();
  refreshInteractive();
  layoutLabels();
  updateUI();
}

/* ── UI handles ────────────────────────────────────────────────────────── */
const dimBtns = { 1: document.getElementById('dim1'), 2: document.getElementById('dim2'),
                  3: document.getElementById('dim3'), all: document.getElementById('dimAll') };
const selBtns = { teal: document.getElementById('selTeal'), terra: document.getElementById('selTerra'),
                  gray: document.getElementById('selGray') };
const slider = document.getElementById('tiltWeight');
const tiltVal = document.getElementById('tiltVal');
const chkTint = document.getElementById('chkTint');
const chkPoint = document.getElementById('chkPoint');
const ptBlock = document.getElementById('ptBlock');
const ptRead = document.getElementById('ptRead');
const signRead = document.getElementById('signRead');
const regionRead = document.getElementById('regionRead');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function fmtW(w) {
  if (dim === 1) return '(' + w.x.toFixed(2) + ')';
  if (dim === 2) return '(' + w.x.toFixed(2) + ', ' + w.y.toFixed(2) + ')';
  return '(' + w.x.toFixed(2) + ', ' + w.y.toFixed(2) + ', ' + w.z.toFixed(2) + ')';
}
function updateUI() {
  for (const k in dimBtns) dimBtns[k].classList.toggle('active', String(panelMode) === k);
  const keys = activeKeys();
  for (const k in selBtns) {
    selBtns[k].disabled = keys.indexOf(k) < 0;
    selBtns[k].style.opacity = selBtns[k].disabled ? 0.4 : 1;
    selBtns[k].classList.toggle('active', k === selected);
  }
  tiltVal.textContent = (+tilt).toFixed(2);
  chkTint.checked = showTint; chkPoint.checked = showPt;
  const on = showPt && panelMode !== 'all';
  ptBlock.style.display = on ? '' : 'none';
  if (!on) return;
  let coords = 'x\u2081 = ' + ptPos.x.toFixed(2);
  if (dim >= 2) coords += ',  x\u2082 = ' + ptPos.y.toFixed(2);
  if (dim >= 3) coords += ',  x\u2083 = ' + ptPos.z.toFixed(2);
  ptRead.textContent = coords;
  let html = '', signs = [];
  keys.forEach(k => {
    const z = preAct(k), s = z >= 0 ? '+' : '\u2212';
    signs.push(s);
    html += '<div><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:' +
      neurons[k].css + ';margin-right:5px"></span>' +
      (k === selected ? '<b>' : '') + 'w = ' + fmtW(weightVec(k)) + ' \u2192 z = ' + z.toFixed(2) +
      ' <b style="color:' + (z >= 0 ? '#1a7f37' : '#b02a2a') + '">' + s + '</b>' +
      (k === selected ? '</b>' : '') + '</div>';
  });
  signRead.innerHTML = html;
  regionRead.innerHTML = 'sign pattern <b>(' + signs.join(', ') + ')</b> \u2014 one of ' +
    Math.pow(2, keys.length) + ' regions cut out by ' + keys.length + ' hyperplane' + (keys.length === 1 ? '' : 's');
}

/* ── mode switching ────────────────────────────────────────────────────── */
function setMode(m) {
  panelMode = m;
  dim = (m === 'all') ? 3 : m;
  [gA, gB, gC].forEach(p => { if (p.parent) p.parent.remove(p); });
  if (m === 'all') {
    gA.position.set(-8.8, 0, 0); gB.position.set(-2.0, 0, 0); gC.position.set(7.0, 0, 0);
    scene.add(gA); scene.add(gB); scene.add(gC);
  } else {
    const p = (m === 1) ? gA : (m === 2) ? gB : gC;
    p.position.set(0, 0, 0); scene.add(p);
  }
  if (activeKeys().indexOf(selected) < 0) selected = 'teal';
  if (dim < 3) ptPos.z = 0;
  if (dim < 2) ptPos.y = 0;
  ptPos.set(cl(ptPos.x, -2.2, 2.2), cl(ptPos.y, -2.2, 2.2), cl(ptPos.z, -2.2, 2.2));

  // fit the camera on the bare panel geometry (tint slabs / point excluded)
  const st = showTint, sp = showPt;
  showTint = false; showPt = false; refresh();
  if (m === 'all')      setCameraView({ projection: 'oblique', obliqueAngleDeg: 30, depthScale: 0.60, heightFraction: 0.86 });
  else if (m === 3)     setCameraView({ projection: 'oblique', obliqueAngleDeg: 30, depthScale: 0.60, heightFraction: 0.80 });
  else                  setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: m === 1 ? 0.80 : 0.82 });
  showTint = st; showPt = sp; refresh();
}

for (const k in dimBtns) (function (kk) {
  dimBtns[kk].addEventListener('click', () => setMode(kk === 'all' ? 'all' : +kk));
})(k);
for (const k in selBtns) (function (kk) {
  selBtns[kk].addEventListener('click', () => { selected = kk; engaged = true; refresh(); });
})(k);
slider.addEventListener('input', () => { tilt = parseFloat(slider.value); engaged = true; refresh(); });
chkTint.addEventListener('change', () => { showTint = chkTint.checked; engaged = true; refresh(); });
chkPoint.addEventListener('change', () => { showPt = chkPoint.checked; engaged = true; refresh(); });

/* ── rebuild occlusion dashing whenever the projection changes ─────────── */
let lastKey = '';
(function watchCam() {
  requestAnimationFrame(watchCam);
  if (!gC.parent) return;
  const os = (window.__figverify && window.__figverify.obliqueState) ? window.__figverify.obliqueState() : null;
  const k = camera.position.toArray().map(v => v.toFixed(2)).join(',') + '|' +
            (camera.zoom || 1).toFixed(3) + '|' + (os ? os.shearAmt.toFixed(3) : 'n');
  if (k !== lastKey) { lastKey = k; buildAxesC(); }
})();

/* ── drag the input point ──────────────────────────────────────────────── */
const rc = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const dragPlane = new THREE.Plane();
let dragging = false;
function setNDC(e) {
  const r = cv.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
cv.addEventListener('pointerdown', e => {
  if (!showPt || !gPoint.parent) return;
  setNDC(e); rc.setFromCamera(ndc, camera);
  if (rc.intersectObject(ptPick, false).length) {
    dragging = true; controls.enabled = false;
    if (panelMode === 3) dragPlane.setFromNormalAndCoplanarPoint(viewerDir(), ptPos.clone());
    else dragPlane.set(V(0, 0, 1), 0);
    try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
  }
});
cv.addEventListener('pointermove', e => {
  if (!dragging) return;
  setNDC(e); rc.setFromCamera(ndc, camera);
  const hit = V(0, 0, 0);
  if (rc.ray.intersectPlane(dragPlane, hit)) {
    ptPos.x = cl(hit.x, -2.2, 2.2);
    ptPos.y = dim >= 2 ? cl(hit.y, -2.2, 2.2) : 0;
    ptPos.z = dim >= 3 ? cl(hit.z, -2.2, 2.2) : 0;
    refresh();
  }
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── guided tour ───────────────────────────────────────────────────────── */
const tour = [
  { title: 'One idea, three input spaces', mode: 'all', w: 1, pt: false, tint: false,
    text: 'A neuron\u2019s decision boundary z = w\u00B7x + b = 0 is a hyperplane: a point on a line (a), a line in a plane (b), a plane in space (c). It always has one dimension less than the input space.' },
  { title: 'a) 1D: the hyperplane is a point', mode: 1, w: 1, pt: true, tint: false,
    text: 'With a single input x\u2081 the pre-activation changes sign at exactly one location \u2014 the teal mark. Drag the blue input point across it and watch z flip sign.' },
  { title: 'Which side is positive?', mode: 1, w: -1, pt: true, tint: true,
    text: 'The tint shows where z > 0. Flipping the weight to w = \u22121 swaps the positive side; the boundary itself does not move.' },
  { title: 'b) 2D: each neuron owns a line', mode: 2, w: 1, pt: true, tint: false,
    text: 'For inputs (x\u2081, x\u2082) each boundary is a line through the origin \u2014 teal for one neuron, orange for another. Two lines cut the plane into four sign regions.' },
  { title: 'Tilting a weight rotates its line', mode: 2, w: 2.2, pt: true, tint: true,
    text: 'Changing the selected neuron\u2019s weight rotates only its own boundary, re-shaping the half-spaces \u2014 the input point can end up in a different region without moving.' },
  { title: 'c) 3D: boundaries become planes', mode: 3, w: 1, pt: false, tint: false,
    text: 'Three neurons give three planes. The axes are dashed exactly where a plane hides them; drag the figure (or press \u201C3D view\u201D) to leave the printed oblique projection and see the occlusion update for real.' }
];
let stepIdx = 0, tweenRaf = null, playTimer = null;
function tweenTilt(target) {
  const start = tilt, t0 = performance.now(), dur = 480;
  if (tweenRaf) cancelAnimationFrame(tweenRaf);
  const stepFn = () => {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    tilt = start + (target - start) * e;
    slider.value = tilt; refresh();
    if (k < 1) tweenRaf = requestAnimationFrame(stepFn);
    else { tilt = target; slider.value = tilt; refresh(); }
  };
  stepFn();
}
function goToStep(i) {
  stepIdx = ((i % tour.length) + tour.length) % tour.length;
  const st = tour[stepIdx];
  showPt = st.pt; showTint = st.tint; selected = 'teal';
  engaged = (stepIdx > 0);
  if (st.mode !== panelMode) setMode(st.mode); else refresh();
  tweenTilt(st.w);
  stepTitle.textContent = (stepIdx + 1) + '/' + tour.length + '  ' + st.title;
  stepText.textContent = st.text;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPlay').addEventListener('click', function () {
  if (playTimer) { clearInterval(playTimer); playTimer = null; this.textContent = 'Play'; return; }
  this.textContent = 'Stop';
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 5200);
});

/* ── start: the printed three-panel composition ────────────────────────── */
document.getElementById('btnReset').style.display = '';
setMode('all');
stepIdx = 0;
stepTitle.textContent = '1/' + tour.length + '  ' + tour[0].title;
stepText.textContent = tour[0].text;
